      ],
      "testNeeded": "none"
    },
    {
      "statement": "The work package cover (IA-S02) shows the temporary instruction attachment field blank at issue time.",
      "type": "finding",
      "status": "supported",
      "sourceIds": [
        "4df0cf7c-f4aa-49ea-a08a-ea4cd74d41f2#1"
      ],
      "testNeeded": "none"
    },
    {
      "statement": "An air-low indication occurred at RHOB while the crew was preparing the boundary; no line opening was authorized.",
      "type": "finding",
      "status": "supported",
      "sourceIds": [
        "incident-description",
        "36f83919-8b7a-4ec0-a789-5d3e24cdaf6f#1"
      ],
      "testNeeded": "none"
    },
    {
      "statement": "The area directory (IA-D01) states it is a location index, not a current piping diagram; valve positions and pressure availability are unknown.",
      "type": "finding",
      "status": "supported",
      "sourceIds": [
        "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc#1"
      ],
      "testNeeded": "none"
    },
    {
      "statement": "Change requirements (IA-D03) require an approved temporary instruction to be attached when the ECP is affected; draft alone does not satisfy distribution.",
      "type": "finding",
      "status": "supported",
      "sourceIds": [
        "26552941-efa6-4cf3-bb10-337c6e62531d#1"
      ],
      "testNeeded": "none"
    }
  ],
  "questions": [
    {
      "intent": "verify_physical_presence_of_temporary_instruction",
      "text": "Was an approved temporary instruction physically attached to the WO-527 work folder despite the blank field on the cover copy?",
      "rationale": "The cover shows a blank attachment field, but record conventions state that empty fields do not prove absence of physical documents. Physical presence would determine whether the crew had an authorized procedure for the current energy-control state.",
      "evidenceNeeded": [
        "Photograph or scan of the inside front page of WO-527 work folder showing any attached temporary instruction",
        "Witness testimony from U-A/U-B regarding what documents were in their possession at 09:48–10:00"
      ],
      "priority": "high",
      "sourceIds": [
        "4df0cf7c-f4aa-49ea-a08a-ea4cd74d41f2#1",
        "0bcc8d12-7f2d-4d73-a6ee-5fefc55c7c84#1"
      ],
      "routedTo": [
        "work-environment"
      ]
    },
    {
      "intent": "verify_boundary_release_status",
      "text": "Was the maintenance boundary formally released (signature obtained) before or during the air interruption at ~10:00 AM?",
      "rationale": "The cover shows signature pending. If release occurred via a separate record not captured on the cover, that would change whether work was authorized under an unrecorded state.",
      "evidenceNeeded": [
        "Signed maintenance acceptance sheet or electronic log showing boundary-release timestamp",
        "Interview with M-A (maintenance receiver) regarding when/where they signed off"
      ],
      "priority": "high",
      "sourceIds": [
        "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc#1",
        "4df0cf7c-f4aa-49ea-a08a-ea4cd74d41f2#1"
      ],
      "routedTo": [
        "work-environment"
      ]
    },
    {
      "intent": "verify_configuration_document_in_use",
      "text": "Which configuration drawing or energy-control procedure did the crew U-A/U-B use to guide valve operations during boundary preparation?",
      "rationale": "The area directory does not establish current piping. If an outdated or incorrect diagram was used, it could explain why valves were left in a state that caused air loss.",
      "evidenceNeeded": [
        "Copy of the drawing held by U-A/U-B at 09:48–10:00",
        "Revision history and distribution log for configuration drawings referenced on WO-527"
      ],
      "priority": "medium",
      "sourceIds": [
        "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc#1",
        "fda75553-eef9-44a7-b3e0-2457fab694d9#1"
      ],
      "routedTo": [
        "work-environment"
      ]
    },
    {
      "intent": "verify_valve_states_at_time_of_event",
      "text": "What were the open/closed states of main-route valves M-101/M-102 and any other isolation valves at RHOB service station when air pressure dropped?",
      "rationale": "Valve state determines whether a procedural error, equipment failure, or upstream event caused the interruption. Unknown valve states prevent causal analysis.",
      "evidenceNeeded": [
        "Field log entries from U-A/U-B recording valve positions",
        "Instrument record showing pressure trend and any manual override events"
      ],
      "priority": "high",
      "sourceIds": [
        "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc#1",
        "incident-description"
      ],
      "routedTo": [
        "work-environment"
      ]
    },
    {
      "intent": "verify_upstream_pressure_source_status",
      "text": "Did the air source or upstream distribution experience a pressure drop, valve closure, or equipment trip at ~10:00 AM?",
      "rationale": "If the interruption originated upstream of RHOB (e.g., compressor trip), then boundary preparation procedure may be irrelevant to cause.",
      "evidenceNeeded": [
        "Compressor/dryer system alarm and event log",
        "Upstream pressure gauge readings or DCS trend for 09:35–10:20"
      ],
      "priority": "high",
      "sourceIds": [
        "incident-description",
        "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc#1"
      ],
      "routedTo": [
        "work-environment"
      ]
    },
    {
      "intent": "verify_briefing_and_change_communication",
      "text": "Did U-A/U-B receive a briefing on any recent changes to the 1SC dryer group or RHOB service station that might affect valve configuration?",
      "rationale": "If a change occurred and was not communicated, crew may have used an outdated procedure leading to incorrect boundary state.",
      "evidenceNeeded": [
        "Change notification log for ECP-1SC-04 Rev3 or related drawings",
        "Briefing attendance sheet content beyond topic line"
      ],
      "priority": "medium",
      "sourceIds": [
        "26552941-efa6-4cf3-bb10-337c6e62531d#1",
        "fda75553-eef9-44a7-b3e0-2457fab694d9#1"
      ],
      "routedTo": [
        "work-environment"
      ]
    }
  ],
  "handoffs": [],
  "decision": {
    "summary": "The procedure-planning tag has identified that boundary preparation was ongoing without a signed release and with an apparent missing temporary instruction. The next step is to verify whether the correct, approved energy-control document (ECP or temporary instruction) was physically present in the crew's possession and whether valve states matched the intended configuration.",
    "evidenceUsed": [
      "IA-S02_work_package_cover.md",
      "36f83919-8b7a-4ec0-a789-5d3e24cdaf6f#1",
      "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc#1"
    ],
    "unknowns": [
      "Physical presence of temporary instruction despite blank cover field",
      "Exact valve states at time of interruption",
      "Whether upstream source or distribution caused the pressure drop",
      "Boundary release status beyond signature on work package cover"
    ],
    "alternatives": [
      "Interruption due to equipment failure unrelated to procedure (e.g., compressor trip)",
      "Procedure was correct but field conditions required deviation not captured in records"
    ],
    "confidence": 0.85
  }
}
